import { expect, rows, runExample, test } from './helpers'

// Example list: reference 2 is the Walters paper with the year and journal changed (Mismatch),
// reference 6 cites a DOI that leads to a different work (Mismatch, but not a correction).
const CORRECTED =
  'Walters, W. H., & Wilder, E. I. (2023). Fabrication and errors in the bibliographic citations generated by ChatGPT. Scientific Reports, 13(1), 14045. https://doi.org/10.1038/s41598-023-41032-5'

const evidence = (page: Parameters<typeof rows>[0], n: number) =>
  rows(page)
    .nth(n - 1)
    .locator('.evidence')

test.describe('corrected reference (APA 7)', () => {
  test('a Mismatch whose record is the same work shows the reference as the record gives it', async ({
    page,
  }) => {
    await runExample(page)
    await page.getByRole('button', { name: 'Show details for reference 2' }).click()
    const panel = evidence(page, 2)
    await expect(panel.getByText('Corrected reference (APA 7)')).toBeVisible()
    await expect(panel.locator('.corrected__text')).toHaveText(CORRECTED)
    await expect(panel.getByText('not by a language model')).toBeVisible()
    await expect(panel.getByText(/sentence case/)).toBeVisible()
  })

  test('Copy reference puts exactly that text on the clipboard', async ({ page, context }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write'])
    await runExample(page)
    await page.getByRole('button', { name: 'Show details for reference 2' }).click()
    await evidence(page, 2).getByRole('button', { name: 'Copy reference' }).click()
    await expect(evidence(page, 2).getByRole('status')).toHaveText('Copied')
    expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(CORRECTED)
  })

  test('says so when the browser refuses to copy', async ({ page }) => {
    await runExample(page)
    await page.evaluate(() => {
      Object.defineProperty(navigator, 'clipboard', {
        value: { writeText: () => Promise.reject(new Error('denied')) },
        configurable: true,
      })
    })
    await page.getByRole('button', { name: 'Show details for reference 2' }).click()
    await evidence(page, 2).getByRole('button', { name: 'Copy reference' }).click()
    await expect(evidence(page, 2).getByRole('status')).toHaveText(
      'Could not copy. Select the text and copy it by hand.',
    )
  })

  test('is not offered when the DOI leads to a different work', async ({ page }) => {
    await runExample(page)
    await expect(rows(page).nth(5).locator('.verdict')).toHaveText('Mismatch')
    await page.getByRole('button', { name: 'Show details for reference 6' }).click()
    await expect(rows(page).nth(5)).toContainText('This DOI leads to a different work')
    await expect(evidence(page, 6)).toBeVisible()
    await expect(evidence(page, 6).getByText('Corrected reference (APA 7)')).toHaveCount(0)
  })

  test('is not offered for Verified, Suspect, or Out-of-index results', async ({ page }) => {
    await runExample(page)
    for (const n of [1, 3, 5]) {
      await page
        .getByRole('button', { name: `Show details for reference ${n}`, exact: true })
        .click()
      await expect(evidence(page, n)).toBeVisible()
      await expect(evidence(page, n).getByText('Corrected reference (APA 7)')).toHaveCount(0)
    }
    await expect(page.getByText('Corrected reference (APA 7)')).toHaveCount(0)
  })

  test('works in Indonesian', async ({ page }) => {
    await runExample(page)
    await page.getByRole('button', { name: 'Switch to Bahasa Indonesia' }).click()
    await page.getByRole('button', { name: 'Tampilkan rincian referensi 2' }).click()
    await expect(page.getByText('Referensi yang dikoreksi (APA 7)')).toBeVisible()
    await expect(page.getByRole('button', { name: 'Salin referensi' })).toBeVisible()
  })
})
